INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/cloudflare-python-workers', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'cloudflare-python-workers', 0, 0, 50, '2026-02-20T04:13:19.581Z', '2026-02-20T05:10:54.252Z', '12a6035f83a48fea0cb08443b291e018dafe97a2f14b21db685e7176cbaaaa1c', '{"id":"majiayu000/claude-skill-registry/cloudflare-python-workers","name":"cloudflare-python-workers","description":{"zh":"Cloudflare Python Workers 是一种强大的工具，允许您使用 Python 编写 Worker 脚本。快速开始您的项目，了解其优势和用法","ja":"Cloudflare Python Workers は、Python で Worker スクリプトを書くことができる強力なツールです。機能と使い方を紹介します","ko":"Cloudflare Python Workers는 Python으로 Worker 스크립트를 작성할 수 있는 강력한 도구입니다. 시작하기 위한 정보를 제공합니다","es":"Los trabajadores de Cloudflare Python permiten a los desarrolladores ejecutar código Python en el borde de la red, mejorando el rendimiento y la seguridad.","fr":"Les workers Cloudflare Python permettent aux développeurs d''exécuter du code Python au niveau du réseau, améliorant les performances et la sécurité.","de":"Die Cloudflare Python Worker ermöglichen es Entwicklern, Python-Code am Rand des Netzwerks auszuführen, um die Leistung und Sicherheit zu verbessern.","pt":"Os Trabalhadores Python da Cloudflare são uma ferramenta poderosa para melhorar a segurança e o desempenho do seu site.","ru":"Работники Cloudflare на Python являются мощным инструментом для улучшения безопасности и производительности вашего сайта.","ar":"عمال بايثون كلاودفلير هي أداة قوية لتحسين أمان موقعك وأدائه.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"Cloudflare Python Workers 入门指南","ja":"Cloudflare Python Workers ガイド","ko":"Cloudflare Python Workers 시작하기","es":"Trabajadores de Cloudflare Python: Guía para Desarrolladores","fr":"Workers Cloudflare Python : Guide pour Développeurs","de":"Cloudflare Python Worker: Entwicklerleitfaden","pt":"Trabalhadores Python Cloudflare","ru":"Работники Cloudflare на Python","ar":"عمال بايثون كلاودفلير","en":"cloudflare-python-workers"},"description":{"zh":"Cloudflare Python Workers 是一种强大的工具，允许您使用 Python 编写 Worker 脚本。快速开始您的项目，了解其优势和用法","ja":"Cloudflare Python Workers は、Python で Worker スクリプトを書くことができる強力なツールです。機能と使い方を紹介します","ko":"Cloudflare Python Workers는 Python으로 Worker 스크립트를 작성할 수 있는 강력한 도구입니다. 시작하기 위한 정보를 제공합니다","es":"Los trabajadores de Cloudflare Python permiten a los desarrolladores ejecutar código Python en el borde de la red, mejorando el rendimiento y la seguridad.","fr":"Les workers Cloudflare Python permettent aux développeurs d''exécuter du code Python au niveau du réseau, améliorant les performances et la sécurité.","de":"Die Cloudflare Python Worker ermöglichen es Entwicklern, Python-Code am Rand des Netzwerks auszuführen, um die Leistung und Sicherheit zu verbessern.","pt":"Os Trabalhadores Python da Cloudflare são uma ferramenta poderosa para melhorar a segurança e o desempenho do seu site.","ru":"Работники Cloudflare на Python являются мощным инструментом для улучшения безопасности и производительности вашего сайта.","ar":"عمال بايثون كلاودفلير هي أداة قوية لتحسين أمان موقعك وأدائه.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"definition":{"en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"features":{"zh":["支持 Python 3.12+","使用 Pyodide 编译为 WebAssembly","提供 workers-py 和 workers-runtime-sdk 包","支持 Wrangler 集成","快速开始项目"],"ja":["Python 3.12+ をサポート","Pyodide を使用して WebAssembly にコンパイル","workers-py と workers-runtime-sdk パッケージを提供","Wrangler 統合をサポート","プロジェクトの迅速な開始"],"ko":["Python 3.12+ 지원","Pyodide를 사용하여 WebAssembly로 컴파일","workers-py와 workers-runtime-sdk 패키지 제공","Wrangler 통합 지원","프로젝트 빠른 시작"],"es":["Compatibilidad con Python 3.12+","Ejecución de código en el borde de la red","Mejora del rendimiento y la seguridad","Integración con Wrangler","Soporte para WebAssembly"],"fr":["Compatibilité avec Python 3.12+","Exécution de code au niveau du réseau","Amélioration des performances et de la sécurité","Intégration avec Wrangler","Prise en charge de WebAssembly"],"de":["Kompatibilität mit Python 3.12+","Ausführung von Code am Rand des Netzwerks","Verbesserung der Leistung und Sicherheit","Integration mit Wrangler","Unterstützung für WebAssembly"],"pt":["Compatibilidade com Python 3.12+","Execução de código Python no edge da rede","Integração com o Wrangler","Suporte a WebAssembly","Versões de pacotes atualizadas"],"ru":["Совместимость с Python 3.12+","Выполнение кода Python на краю сети","Интеграция с Wrangler","Поддержка WebAssembly","Обновленные версии пакетов"],"ar":["توافق مع بايثون 3.12+","تشغيل код بايثون على حافة الشبكة","دمج مع Wrangler","دعم ويب 어семبلي","إصدارات حزمة محدثة"]},"keywords":{"zh":["Cloudflare Python Workers","Pyodide","WebAssembly","Worker 脚本","Python 编程","Cloudflare Workers","Wrangler","workers-py","workers-runtime-sdk"],"ja":["Cloudflare Python Workers","Pyodide","WebAssembly","Worker スクリプト","Python プログラミング","Cloudflare Workers","Wrangler","workers-py","workers-runtime-sdk"],"ko":["Cloudflare Python Workers","Pyodide","WebAssembly","Worker 스크립트","Python 프로그래밍","Cloudflare Workers","Wrangler","workers-py","workers-runtime-sdk"],"es":["trabajadores de Cloudflare Python","desarrollo web","rendimiento web","seguridad web","Python en el borde de la red","WebAssembly","Wrangler"],"fr":["workers Cloudflare Python","développement web","performances web","sécurité web","Python au niveau du réseau","WebAssembly","Wrangler"],"de":["Cloudflare Python Worker","Webentwicklung","Webleistung","Websicherheit","Python am Rand des Netzwerks","WebAssembly","Wrangler"],"pt":["Trabalhadores Python Cloudflare","Desenvolvimento web","Segurança da web","Desempenho da web","Python no edge","WebAssembly","Wrangler"],"ru":["Работники Cloudflare на Python","Веб-разработка","Веб-безопасность","Веб-производительность","Python на краю","WebAssembly","Wrangler"],"ar":["عمال بايثون كلاودفلير","تطوير الويب","أمان الويب","أداء الويب","بايثون على حافة","ويب 어семبلي","Wrangler"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.581Z","topics":[],"category":"community","skillMd":{"name":"cloudflare-python-workers","description":"|","bodyPreview":"# Cloudflare Python Workers\n\n**Status**: Beta (requires `python_workers` compatibility flag)\n**Runtime**: Pyodide (Python 3.12+ compiled to WebAssembly)\n**Package Versions**: workers-py@1.7.0, workers-runtime-sdk@0.3.1, wrangler@4.58.0\n**Last Verified**: 2026-01-21\n\n## Quick Start (5 Minutes)\n\n### 1. Prerequisites\n\nEnsure you have installed:\n- [uv](https://docs.astral.sh/uv/#installation) - Python package manager\n- [Node.js](https://nodejs.org/) - Required for Wrangler\n\n### 2. Initialize Project","body":"# Cloudflare Python Workers\n\n**Status**: Beta (requires `python_workers` compatibility flag)\n**Runtime**: Pyodide (Python 3.12+ compiled to WebAssembly)\n**Package Versions**: workers-py@1.7.0, workers-runtime-sdk@0.3.1, wrangler@4.58.0\n**Last Verified**: 2026-01-21\n\n## Quick Start (5 Minutes)\n\n### 1. Prerequisites\n\nEnsure you have installed:\n- [uv](https://docs.astral.sh/uv/#installation) - Python package manager\n- [Node.js](https://nodejs.org/) - Required for Wrangler\n\n### 2. Initialize Project\n\n```bash\n# Create project directory\nmkdir my-python-worker && cd my-python-worker\n\n# Initialize Python project\nuv init\n\n# Install pywrangler\nuv tool install workers-py\n\n# Initialize Worker configuration\nuv run pywrangler init\n```\n\n### 3. Create Entry Point\n\nCreate `src/entry.py`:\n\n```python\nfrom workers import WorkerEntrypoint, Response\n\nclass Default(WorkerEntrypoint):\n    async def fetch(self, request):\n        return Response(\"Hello from Python Worker!\")\n```\n\n### 4. Configure wrangler.jsonc\n\n```jsonc\n{\n  \"name\": \"my-python-worker\",\n  \"main\": \"src/entry.py\",\n  \"compatibility_date\": \"2025-12-01\",\n  \"compatibility_flags\": [\"python_workers\"]\n}\n```\n\n### 5. Run Locally\n\n```bash\nuv run pywrangler dev\n# Visit http://localhost:8787\n```\n\n### 6. Deploy\n\n```bash\nuv run pywrangler deploy\n```\n\n---\n\n## Migration from Pre-December 2025 Workers\n\nIf you created a Python Worker before December 2025, you were limited to built-in packages. With pywrangler (Dec 2025), you can now deploy with external packages.\n\n**Old Approach** (no longer needed):\n```python\n# Limited to built-in packages only\n# Could only use httpx, aiohttp, beautifulsoup4, etc.\n# Error: \"You cannot yet deploy Python Workers that depend on\n# packages defined in requirements.txt [code: 10021]\"\n```\n\n**New Approach** (pywrangler):\n```toml\n# pyproject.toml\n[project]\ndependencies = [\"fastapi\", \"any-pyodide-compatible-package\"]\n```\n\n```bash\nuv tool install workers-py\nuv run pywrangler deploy  # Now works!\n```\n\n**Historical Timeline**:\n- **April 2024 - Dec 2025**: Package deployment completely blocked\n- **Dec 8, 2025**: Pywrangler released, enabling package deployment\n- **Jan 2026**: Open beta with full package support\n\n**See**: [Package deployment issue history](https://github.com/cloudflare/workers-sdk/issues/6613)\n\n---\n\n## Core Concepts\n\n### WorkerEntrypoint Class Pattern\n\nAs of August 2025, Python Workers use a class-based pattern (not global handlers):\n\n```python\nfrom workers import WorkerEntrypoint, Response\n\nclass Default(WorkerEntrypoint):\n    async def fetch(self, request):\n        # Access bindings via self.env\n        value = await self.env.MY_KV.get(\"key\")\n\n        # Parse request\n        url = request.url\n        method = request.method\n\n        return Response(f\"Method: {method}, URL: {url}\")\n```\n\n### Accessing Bindings\n\nAll Cloudflare bindings are accessed via `self.env`:\n\n```python\nclass Default(WorkerEntrypoint):\n    async def fetch(self, request):\n        # D1 Database\n        result = await self.env.DB.prepare(\"SELECT * FROM users\").all()\n\n        # KV Storage\n        value = await self.env.MY_KV.get(\"key\")\n        await self.env.MY_KV.put(\"key\", \"value\")\n\n        # R2 Object Storage\n        obj = await self.env.MY_BUCKET.get(\"file.txt\")\n\n        # Workers AI\n        response = await self.env.AI.run(\"@cf/meta/llama-2-7b-chat-int8\", {\n            \"prompt\": \"Hello!\"\n        })\n\n        return Response(\"OK\")\n```\n\n**Supported Bindings**:\n- D1 (SQL database)\n- KV (key-value storage)\n- R2 (object storage)\n- Workers AI\n- Vectorize\n- Durable Objects\n- Queues\n- Analytics Engine\n\nSee [Cloudflare Bindings Documentation](https://developers.cloudflare.com/workers/runtime-apis/bindings/) for details.\n\n### Request/Response Handling\n\n```python\nfrom workers import WorkerEntrypoint, Response\nimport json\n\nclass Default(WorkerEntrypoint):\n    async def fetch(self, request):\n        # Parse JSON body\n        if request.method == \"POST\":\n            body = await request.json()\n            return Response(\n                json.dumps({\"received\": body}),\n                headers={\"Content-Type\": \"application/json\"}\n            )\n\n        # Query parameters\n        url = URL(request.url)\n        name = url.searchParams.get(\"name\", \"World\")\n\n        return Response(f\"Hello, {name}!\")\n```\n\n### Scheduled Handlers (Cron)\n\n```python\nfrom workers import handler\n\n@handler\nasync def on_scheduled(event, env, ctx):\n    # Run on cron schedule\n    print(f\"Cron triggered at {event.scheduledTime}\")\n\n    # Do work...\n    await env.MY_KV.put(\"last_run\", str(event.scheduledTime))\n```\n\nConfigure in wrangler.jsonc:\n\n```jsonc\n{\n  \"triggers\": {\n    \"crons\": [\"*/5 * * * *\"]  // Every 5 minutes\n  }\n}\n```\n\n---\n\n## Python Workflows\n\nPython Workflows enable durable, multi-step automation with automatic retries and state persistence.\n\n### Why Decorator Pattern?\n\nPython Workflows use the `@step.do()` decorator pattern because **Python does not easily support anonymous callbacks** (unlike JavaScript/TypeScript which allows inline arrow functions). This is a fundamental language difference, not a limitation of Cloudflare''s implementation.\n\n**JavaScript Pattern** (doesn''t translate):\n```javascript\nawait step.do(\"my step\", async () => {\n  // Inline callback\n  return result;\n});\n```\n\n**Python Pattern** (required):\n```python\n@step.do(\"my step\")\nasync def my_step():\n    # Named function with decorator\n    return result\n\nresult = await my_step()\n```\n\n**Source**: [Python Workflows Blog](https://blog.cloudflare.com/python-workflows/)\n\n### Concurrency with asyncio.gather\n\nPyodide captures JavaScript promises (thenables) and proxies them as Python awaitables. This enables `Promise.all`-equivalent behavior using standard Python async patterns:\n\n```python\nimport asyncio\n\n@step.do(\"step_a\")\nasync def step_a():\n    return \"A\"\n\n@step.do(\"step_b\")\nasync def step_b():\n    return \"B\"\n\n# Concurrent execution (like Promise.all)\nresults = await asyncio.gather(step_a(), step_b())\n# results = [\"A\", \"B\"]\n```\n\n**Why This Works**: JavaScript promises from workflow steps are proxied as Python awaitables, allowing standard asyncio concurrency primitives.\n\n**Source**: [Python Workflows Blog](https://blog.cloudflare.com/python-workflows/)\n\n### Basic Workflow\n\n```python\nfrom workers import WorkflowEntrypoint, WorkerEntrypoint, Response\n\nclass MyWorkflow(WorkflowEntrypoint):\n    async def run(self, event, step):\n        # Step 1\n        @step.do(\"fetch data\")\n        async def fetch_data():\n            response = await fetch(\"https://api.example.com/data\")\n            return await response.json()\n\n        data = await fetch_data()\n\n        # Step 2: Sleep\n        await step.sleep(\"wait\", \"10 seconds\")\n\n        # Step 3: Process\n        @step.do(\"process data\")\n        async def process_data():\n            return {\"processed\": True, \"count\": len(data)}\n\n        result = await process_data()\n        return result\n\n\nclass Default(WorkerEntrypoint):\n    async def fetch(self, request):\n        # Create workflow instance\n        instance = await self.env.MY_WORKFLOW.create()\n        return Response(f\"Workflow started: {instance.id}\")\n```\n\n### DAG Dependencies\n\nDefine step dependencies for parallel execution:\n\n```python\nclass MyWorkflow(WorkflowEntrypoint):\n    async def run(self, event, step):\n        @step.do(\"step_a\")\n        async def step_a():\n            return \"A done\"\n\n        @step.do(\"step_b\")\n        async def step_b():\n            return \"B done\"\n\n        # step_c waits for both step_a and step_b\n        @step.do(\"step_c\", depends=[step_a, step_b], concurrent=True)\n        async def step_c(result_a, result_b):\n            return f\"C received: {result_a}, {result_b}\"\n\n        return await step_c()\n```\n\n### Workflow Configuration\n\n```jsonc\n{\n  \"compatibility_flags\": [\"python_workers\", \"python_workflows\"],\n  \"compatibility_date\": \"2025-12-01\",\n  \"workflows\": [\n    {\n      \"name\": \"my-workflow\",\n      \"binding\": \"MY_WORKFLOW\",\n      \"class_name\": \"MyWorkflow\"\n    }\n  ]\n}\n```\n\n---\n\n## Package Management\n\n### pyproject.toml Configuration\n\n```toml\n[project]\nname = \"my-python-worker\"\nversion = \"0.1.0\"\nrequires-python = \">=3.12\"\ndependencies = [\n    \"beautifulsoup4\",\n    \"httpx\"\n]\n\n[dependency-groups]\ndev = [\n    \"workers-py\",\n    \"workers-runtime-sdk\"\n]\n```\n\n### Supported Packages\n\nPython Workers support:\n- **Pure Python packages** from PyPI\n- **Pyodide packages** (pre-built for WebAssembly)\n\nSee [Pyodide packages list](https://pyodide.org/en/stable/usage/packages-in-pyodide.html).\n\n### HTTP Clients\n\nOnly **async** HTTP libraries work:\n\n```python\n# ✅ WORKS - httpx (async)\nimport httpx\n\nasync with httpx.AsyncClient() as client:\n    response = await client.get(\"https://api.example.com\")\n\n# ✅ WORKS - aiohttp\nimport aiohttp\n\nasync with aiohttp.ClientSession() as session:\n    async with session.get(\"https://api.example.com\") as response:\n        data = await response.json()\n\n# ❌ DOES NOT WORK - requests (sync)\nimport requests  # Will fail!\n```\n\n### Requesting New Packages\n\nRequest support for new packages at:\nhttps://github.com/cloudflare/workerd/discussions/categories/python-packages\n\n---\n\n## FFI (Foreign Function Interface)\n\nAccess JavaScript APIs from Python via Pyodide''s FFI:\n\n### JavaScript Globals\n\n```python\nfrom js import fetch, console, Response as JSResponse\n\nclass Default(WorkerEntrypoint):\n    async def fetch(self, request):\n        # Use JavaScript fetch\n        response = await fetch(\"https://api.example.com\")\n        data = await response.json()\n\n        # Console logging\n        console.log(\"Fetched data:\", data)\n\n        # Return JavaScript Response\n        return JSResponse.new(\"Hello!\")\n```\n\n### Type Conversions\n\n**Important**: `to_py()` is a METHOD on JavaScript objects, not a standalone function. Only `to_js()` is a function.\n\n```python\nfrom js import Object\nfrom pyodide.ffi import to_js\n\n# ❌ WRONG - ImportError!\nfrom pyodide.ffi import to_py\npython_data = to_py(js_data)\n\n# ✅ CORRECT - to_py() is a method\nasync def fetch(self, request):\n    data = await request.json()  # Returns JS object\n    python_data = data.to_py()   # Convert to Python dict\n\n# Convert Python dict to JavaScript object\npython_dict = {\"name\": \"test\", \"count\": 42}\njs_object = to_js(python_dict, dict_converter=Object.fromEntries)\n\n# Use in Response\nreturn Response(to_js({\"status\": \"ok\"}))\n```\n\n**Source**: [GitHub Issue #3322](https://github.com/cloudflare/workerd/issues/3322) (Pyodide maintainer clarification)\n\n---\n\n## Known Issues Prevention\n\nThis skill prevents **11 documented issues**:\n\n### Issue #1: Legacy Handler Pattern\n\n**Error**: `TypeError: on_fetch is not defined`\n\n**Why**: Handler pattern changed in August 2025.\n\n```python\n# ❌ OLD (deprecated)\n@handler\nasync def on_fetch(request):\n    return Response(\"Hello\")\n\n# ✅ NEW (current)\nclass Default(WorkerEntrypoint):\n    async def fetch(self, request):\n        return Response(\"Hello\")\n```\n\n### Issue #2: Sync HTTP Libraries\n\n**Error**: `RuntimeError: cannot use blocking call in async context`\n\n**Why**: Python Workers run async-only. Sync libraries block the event loop.\n\n```python\n# ❌ FAILS\nimport requests\nresponse = requests.get(\"https://api.example.com\")\n\n# ✅ WORKS\nimport httpx\nasync with httpx.AsyncClient() as client:\n    response = await client.get(\"https://api.example.com\")\n```\n\n### Issue #3: Native/Compiled Packages\n\n**Error**: `ModuleNotFoundError: No module named ''numpy''` (or similar)\n\n**Why**: Only pure Python packages work. Native C extensions are not supported.\n\n**Solution**: Use Pyodide-compatible alternatives or check [Pyodide packages](https://pyodide.org/en/stable/usage/packages-in-pyodide.html).\n\n### Issue #4: Missing Compatibility Flags\n\n**Error**: `Error: Python Workers require the python_workers compatibility flag`\n\n**Fix**: Add to wrangler.jsonc:\n\n```jsonc\n{\n  \"compatibility_flags\": [\"python_workers\"]\n}\n```\n\nFor Workflows, also add `\"python_workflows\"`.\n\n### Issue #5: I/O Outside Workflow Steps\n\n**Error**: Workflow state not persisted correctly\n\n**Why**: All I/O must happen inside `@step.do` for durability.\n\n```python\n# ❌ BAD - fetch outside step\nresponse = await fetch(\"https://api.example.com\")\n@step.do(\"use data\")\nasync def use_data():\n    return await response.json()  # response may be stale on retry\n\n# ✅ GOOD - fetch inside step\n@step.do(\"fetch and use\")\nasync def fetch_and_use():\n    response = await fetch(\"https://api.example.com\")\n    return await response.json()\n```\n\n### Issue #6: Type Serialization Errors\n\n**Error**: `TypeError: Object of type X is not JSON serializable`\n\n**Why**: Workflow step return values must be JSON-serializable.\n\n**Fix**: Convert complex objects before returning:\n\n```python\n@step.do(\"process\")\nasync def process():\n    # Convert datetime to string\n    return {\"timestamp\": datetime.now().isoformat()}\n```\n\n### Issue #7: Cold Start Performance\n\n**Note**: Python Workers have higher cold starts than JavaScript. With Wasm memory snapshots (Dec 2025), heavy packages like FastAPI and Pydantic now load in **~1 second** (down from ~10 seconds previously), but this is still ~2x slower than JavaScript Workers (~50ms).\n\n**Performance Numbers** (as of Dec 2025):\n- **Before snapshots**: ~10 seconds for FastAPI/Pydantic\n- **After snapshots**: ~1 second (10x improvement)\n- **JavaScript equivalent**: ~50ms\n\n**Mitigation**:\n- Minimize top-level imports\n- Use lazy loading for heavy packages\n- Consider JavaScript Workers for latency-critical paths\n- Wasm snapshots automatically improve cold starts (no config needed)\n\n**Source**: [Python Workers Redux Blog](https://blog.cloudflare.com/python-workers-advancements/) | [InfoQ Coverage](https://www.infoq.com/news/2025/12/cloudflare-wasm-python-snapshot/)\n\n### Issue #8: Package Installation Failures\n\n**Error**: `Failed to install package X`\n\n**Causes**:\n- Package has native dependencies\n- Package not in Pyodide ecosystem\n- Network issues during bundling\n\n**Fix**: Check package compatibility, use alternatives, or request support.\n\n### Issue #9: Dev Registry Breaks JS-to-Python RPC\n\n**Error**: `Network connection lost` when calling Python Worker from JavaScript Worker\n**Source**: [GitHub Issue #11438](https://github.com/cloudflare/workers-sdk/issues/11438)\n\n**Why It Happens**: Dev registry doesn''t properly route RPC calls between separately-run Workers in different terminals.\n\n**Prevention**:\n```bash\n# ❌ Doesn''t work - separate terminals\n# Terminal 1: npx wrangler dev (JS worker)\n# Terminal 2: npx wrangler dev (Python worker)\n# Result: Network connection lost error\n\n# ✅ Works - single wrangler instance\nnpx wrangler dev -c ts/wrangler.jsonc -c py/wrangler.jsonc\n```\n\nRun both workers in a single wrangler instance to enable proper RPC communication.\n\n### Issue #10: HTMLRewriter Memory Limit with Data URLs\n\n**Error**: `TypeError: Parser error: The memory limit has been exceeded`\n**Source**: [GitHub Issue #10814](https://github.com/cloudflare/workers-sdk/issues/10814)\n\n**Why It Happens**: Large inline `data:` URLs (>10MB) in HTML trigger parser memory limits. This is NOT about response size—10MB plain text works fine, but 10MB HTML with embedded data URLs fails. Common with Python Jupyter Notebooks that use inline images for plots.\n\n**Prevention**:\n```python\n# ❌ FAILS - HTMLRewriter triggered on notebook HTML with data: URLs\nresponse = await fetch(\"https://origin.example.com/notebook.html\")\nreturn response  # Crashes if HTML contains large data: URLs\n\n# ✅ WORKS - Stream directly or use text/plain\nresponse = await fetch(\"https://origin.example.com/notebook.html\")\nheaders = {\"Content-Type\": \"text/plain\"}  # Bypass parser\nreturn Response(await response.text(), headers=headers)\n```\n\n**Workarounds**:\n- Avoid HTMLRewriter on notebook content (stream directly)\n- Pre-process notebooks to extract data URLs to external files\n- Use `text/plain` content-type to bypass parser\n\n### Issue #11: PRNG Cannot Be Seeded During Initialization\n\n**Error**: Deployment fails with user error\n**Source**: [Python Workers Redux Blog](https://blog.cloudflare.com/python-workers-advancements/)\n\n**Why It Happens**: Wasm snapshots don''t support PRNG initialization before request handlers. If you call pseudorandom number generator APIs (like `random.seed()`) during module initialization, deployment FAILS.\n\n**Prevention**:\n```python\nimport random\n\n# ❌ FAILS deployment - module-level PRNG call\nrandom.seed(42)\n\nclass Default(WorkerEntrypoint):\n    async def fetch(self, request):\n        return Response(str(random.randint(1, 100)))\n\n# ✅ WORKS - PRNG calls inside handlers\nclass Default(WorkerEntrypoint):\n    async def fetch(self, request):\n        random.seed(42)  # Initialize inside handler\n        return Response(str(random.randint(1, 100)))\n```\n\nOnly call PRNG functions inside request handlers, not at module level.\n\n---\n\n## Best Practices\n\n### Always Do\n\n- Use `WorkerEntrypoint` class pattern\n- Use async HTTP clients (httpx, aiohttp)\n- Put all I/O inside workflow steps\n- Add `python_workers` compatibility flag\n- Use `self.env` for all bindings\n- Return JSON-serializable data from workflow steps\n\n### Never Do\n\n- Use sync HTTP libraries (requests)\n- Use native/compiled packages\n- Perform I/O outside workflow steps\n- Use legacy `@handler` decorator for fetch\n- Expect JavaScript-level cold start times\n\n---\n\n## Framework Note: FastAPI\n\nFastAPI can work with Python Workers but with limitations:\n\n```python\nfrom fastapi import FastAPI\nfrom workers import WorkerEntrypoint\n\napp = FastAPI()\n\n@app.get(\"/\")\nasync def root():\n    return {\"message\": \"Hello from FastAPI\"}\n\nclass Default(WorkerEntrypoint):\n    async def fetch(self, request):\n        # Route through FastAPI\n        return await app(request)\n```\n\n**Limitations**:\n- Async-only (no sync endpoints)\n- No WSGI middleware\n- Beta stability\n\nSee [Cloudflare FastAPI example](https://developers.cloudflare.com/workers/languages/python/) for details.\n\n---\n\n## Official Documentation\n\n- [Python Workers Overview](https://developers.cloudflare.com/workers/languages/python/)\n- [Python Workers Basics](https://developers.cloudflare.com/workers/languages/python/basics/)\n- [How Python Workers Work](https://developers.cloudflare.com/workers/languages/python/how-python-workers-work/)\n- [Python Packages](https://developers.cloudflare.com/workers/languages/python/packages/)\n- [FFI (Foreign Function Interface)](https://developers.cloudflare.com/workers/languages/python/ffi/)\n- [Python Workflows](https://developers.cloudflare.com/workflows/python/)\n- [Pywrangler CLI](https://github.com/cloudflare/workers-py)\n- [Pyodide Package List](https://pyodide.org/en/stable/usage/packages-in-pyodide.html)\n\n---\n\n## Dependencies\n\n```json\n{\n  \"workers-py\": \"1.7.0\",\n  \"workers-runtime-sdk\": \"0.3.1\",\n  \"wrangler\": \"4.58.0\"\n}\n```\n\n**Note**: Always pin versions for reproducible builds. Check [PyPI workers-py](https://pypi.org/project/workers-py/) for latest releases.\n\n---\n\n## Production Validation\n\n- Cloudflare changelog: Dec 8, 2025 (Pywrangler + cold start improvements)\n- workers-py 1.7.0: Latest stable (Jan 2026)\n- Python Workflows beta: Aug 22, 2025\n- Handler pattern change: Aug 14, 2025\n\n**Compatibility Date Guidance**:\n- Use `2025-12-01` for new projects (latest features including pywrangler improvements)\n- Use `2025-08-01` only if you need to match older production Workers\n"},"lastSynced":"2026-02-20T05:10:54.252Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloud Computing Agents needing advanced Python worker capabilities on Cloudflare","zh":"非常适合需要在Cloudflare上运行高级Python worker能力的云计算代理","ja":"Cloudflareで高度なPythonワーカーキャパビリティを必要とするクラウドコンピューティングエージェントに最適","ko":"Cloudflare에서 고급 Python 워커 기능이 필요한 클라우드 컴퓨팅 에이전트에 적합","es":"Perfecto para agentes de computación en la nube que necesitan capacidades de trabajadores de Python avanzadas en Cloudflare","fr":"Parfait pour les agents de cloud computing qui nécessitent des capacités de travailleurs Python avancées sur Cloudflare","de":"Perfekt für Cloud-Computing-Agents, die erweiterte Python-Worker-Fähigkeiten auf Cloudflare benötigen","pt":"Perfeito para agentes de computação em nuvem que precisam de capacidades avançadas de trabalhador Python no Cloudflare","ru":"Идеально подходит для агентов облачных вычислений, которым необходимы расширенные возможности рабочих процессов Python в Cloudflare","ar":"مثالي لعمليات الوكيل الحاسوبي السحابي التي تحتاج إلى إمكانيات متقدمة لعميل Python على Cloudflare"},"recommendation":{"en":"Empowers agents to deploy and manage Python workers on Cloudflare using Pyodide, with access to workers-py and workers-runtime-sdk libraries, and leveraging Wrangler for project management, all compiled to WebAssembly for efficient execution","zh":"赋予代理部署和管理Cloudflare上的Python worker的能力，使用Pyodide，访问workers-py和workers-runtime-sdk库，并利用Wrangler进行项目管理，所有编译到WebAssembly以实现高效执行","ja":"Pyodideを使用してCloudflare上でPythonワーカーをデプロイおよび管理するエージェントを可能にし、workers-pyおよびworkers-runtime-sdkライブラリにアクセスし、Wranglerを使用してプロジェクトを管理し、すべてWebAssemblyにコンパイルして効率的な実行を実現","ko":"Pyodide를 사용하여 Cloudflare에서 Python 워커를 배포 및 관리할 수 있는 에이전트를 가능하게 하며, workers-py 및 workers-runtime-sdk 라이브러리에 액세스하고, Wrangler를 사용하여 프로젝트를 관리하며, 모든 것을 WebAssembly로 컴파일하여 효율적인 실행을实现","es":"Habilita a los agentes a implementar y administrar trabajadores de Python en Cloudflare mediante Pyodide, con acceso a las bibliotecas workers-py y workers-runtime-sdk, y aprovechando Wrangler para la administración de proyectos, todo compilado a WebAssembly para una ejecución eficiente","fr":"Permet aux agents de déployer et de gérer des travailleurs Python sur Cloudflare à l''aide de Pyodide, avec un accès aux bibliothèques workers-py et workers-runtime-sdk, et en exploitant Wrangler pour la gestion de projet, le tout compilé en WebAssembly pour une exécution efficace","de":"Ermächtigt Agenten, Python-Worker auf Cloudflare mithilfe von Pyodide zu deployen und zu verwalten, mit Zugriff auf die Bibliotheken workers-py und workers-runtime-sdk, und nutzt Wrangler für Projektmanagement, alles kompiliert zu WebAssembly für eine effiziente Ausführung","pt":"Habilita os agentes a implantar e gerenciar trabalhadores Python no Cloudflare usando Pyodide, com acesso às bibliotecas workers-py e workers-runtime-sdk, e aproveitando o Wrangler para gerenciamento de projetos, tudo compilado para WebAssembly para execução eficiente","ru":"Предоставляет агентам возможность развертывать и управлять рабочими процессами Python в Cloudflare с использованием Pyodide, имея доступ к библиотекам workers-py и workers-runtime-sdk, и используя Wrangler для управления проектами, все скомпилированное в WebAssembly для эффективного выполнения","ar":"تمكّن الوكيل من نشر وتشغيل عميل Python على Cloudflare باستخدام Pyodide، مع الوصول إلى مكتبات workers-py و workers-runtime-sdk، وتفويض Wrangler لإدارة المشاريع، وكل شيء يُجمع في WebAssembly للتشغيل الفعال"},"useCases":{"en":["Deploying serverless Python applications on Cloudflare","Managing worker scripts with Wrangler","Utilizing Pyodide for Python 3.12+ compatibility"],"zh":["在Cloudflare上部署无服务器Python应用程序","使用Wrangler管理worker脚本","利用Pyodide实现Python 3.12+兼容性"],"ja":["Cloudflare上でサーバーレスPythonアプリケーションをデプロイ","Wranglerを使用してワーカースクリプトを管理","Pyodideを使用してPython 3.12+の互換性を実現"],"ko":["Cloudflare에서 서버리스 Python 애플리케이션을 배포","Wrangler를 사용하여 워커 스크립트를 관리","Pyodide를 사용하여 Python 3.12+ 호환성을 구현"],"es":["Implementación de aplicaciones Python sin servidor en Cloudflare","Administración de scripts de trabajadores con Wrangler","Uso de Pyodide para la compatibilidad con Python 3.12+"],"fr":["Déploiement d''applications Python sans serveur sur Cloudflare","Gestion de scripts de travailleurs avec Wrangler","Utilisation de Pyodide pour la compatibilité Python 3.12+"],"de":["Bereitstellung von serverlosen Python-Anwendungen auf Cloudflare","Verwaltung von Worker-Skripten mit Wrangler","Verwendung von Pyodide für die Kompatibilität mit Python 3.12+"],"pt":["Implantação de aplicações Python sem servidor no Cloudflare","Gerenciamento de scripts de trabalhador com Wrangler","Utilização de Pyodide para compatibilidade com Python 3.12+"],"ru":["Развертывание бессерверных приложений Python в Cloudflare","Управление скриптами рабочих процессов с помощью Wrangler","Использование Pyodide для совместимости с Python 3.12+"],"ar":["نشر تطبيقات Python بدون خادم على Cloudflare","إدارة نصوص العاملين مع Wrangler","استخدام Pyodide للتوافق مع Python 3.12+"]},"limitations":{"en":["Requires python_workers compatibility flag","Node.js installation for Wrangler","Pyodide runtime with Python 3.12+ compiled to WebAssembly"],"zh":["需要python_workers兼容性标志","需要Node.js安装Wrangler","需要Pyodide运行时，Python 3.12+编译到WebAssembly"],"ja":["python_workers互換性フラグが必要","WranglerのインストールにはNode.jsが必要","Pyodideランタイムが必要、Python 3.12+をWebAssemblyにコンパイル"],"ko":["python_workers 호환성 플래그가 필요","Wrangler 설치를 위해 Node.js가 필요","Pyodide 런타임이 필요, Python 3.12+를 WebAssembly로 컴파일"],"es":["Requiere la compatibilidad con la bandera python_workers","Instalación de Node.js para Wrangler","Tiempo de ejecución de Pyodide con Python 3.12+ compilado a WebAssembly"],"fr":["Nécessite la compatibilité avec le drapeau python_workers","Installation de Node.js pour Wrangler","Temps d''exécution de Pyodide avec Python 3.12+ compilé en WebAssembly"],"de":["Benötigt die Kompatibilität mit der python_workers-Flagge","Installation von Node.js für Wrangler","Laufzeit von Pyodide mit Python 3.12+ kompiliert zu WebAssembly"],"pt":["Requer compatibilidade com a flag python_workers","Instalação do Node.js para Wrangler","Tempo de execução Pyodide com Python 3.12+ compilado para WebAssembly"],"ru":["Требует совместимости с флагом python_workers","Установка Node.js для Wrangler","Время выполнения Pyodide с Python 3.12+ скомпилированным в WebAssembly"],"ar":["يتطلب توافق مع علم compatibility python_workers","تثبيت Node.js من أجل Wrangler","زمن تشغيل Pyodide مع Python 3.12+ مجمّع في WebAssembly"]},"version":3},"contentHash":"12a6035f83a48fea0cb08443b291e018dafe97a2f14b21db685e7176cbaaaa1c","qualityScore":50}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('evolv3ai/claude-skills-archive/cloudflare-python-workers', 'community', 'evolv3ai', 'claude-skills-archive', 'evolv3ai/claude-skills-archive', 'cloudflare-python-workers', 0, 0, 50, '2026-02-20T04:13:19.581Z', '2026-02-20T05:10:46.601Z', '12a6035f83a48fea0cb08443b291e018dafe97a2f14b21db685e7176cbaaaa1c', '{"id":"evolv3ai/claude-skills-archive/cloudflare-python-workers","name":"cloudflare-python-workers","description":{"zh":"Cloudflare Python Workers 是一个生产就绪的技能，支持 Cloudflare、React、Tailwind v4 和 AI 集成","ja":"Cloudflare Python Workers は、Cloudflare、React、Tailwind v4、AI 統合をサポートするプロダクションレディのスキルです","ko":"Cloudflare Python Workers는 Cloudflare, React, Tailwind v4 및 AI 통합을 지원하는生产就绪 스킬입니다","es":"Los trabajadores de Python de Cloudflare permiten ejecutar código Python en el borde de la red","fr":"Les workers Python de Cloudflare permettent d''exécuter du code Python au bord du réseau","de":"Die Cloudflare Python Worker ermöglichen die Ausführung von Python-Code am Netzwerkrand","pt":"Os trabalhadores Python Cloudflare são uma habilidade de produção pronta para o Claude Code CLI","ru":"Работники Python Cloudflare - это производительная способность для Claude Code CLI","ar":"عاملو بایتون كلاودفلير هي مهارة جاهزة للإنتاج ل كلود كود سي ال آي","en":"Production-ready skills for Claude Code CLI - Cloudflare, React, Tailwind v4, and AI integrations"},"seo":{"title":{"zh":"Cloudflare Python Workers 入门指南","ja":"Cloudflare Python Workers ガイド","ko":"Cloudflare Python Workers 시작하기","es":"Trabajadores de Python de Cloudflare","fr":"Workers Python de Cloudflare","de":"Cloudflare Python Worker","pt":"Trabalhadores Python Cloudflare","ru":"Работники Python Cloudflare","ar":"عاملو بایتون كلاودفلير","en":"cloudflare-python-workers"},"description":{"zh":"Cloudflare Python Workers 是一个生产就绪的技能，支持 Cloudflare、React、Tailwind v4 和 AI 集成","ja":"Cloudflare Python Workers は、Cloudflare、React、Tailwind v4、AI 統合をサポートするプロダクションレディのスキルです","ko":"Cloudflare Python Workers는 Cloudflare, React, Tailwind v4 및 AI 통합을 지원하는生产就绪 스킬입니다","es":"Los trabajadores de Python de Cloudflare permiten ejecutar código Python en el borde de la red","fr":"Les workers Python de Cloudflare permettent d''exécuter du code Python au bord du réseau","de":"Die Cloudflare Python Worker ermöglichen die Ausführung von Python-Code am Netzwerkrand","pt":"Os trabalhadores Python Cloudflare são uma habilidade de produção pronta para o Claude Code CLI","ru":"Работники Python Cloudflare - это производительная способность для Claude Code CLI","ar":"عاملو بایتون كلاودفلير هي مهارة جاهزة للإنتاج ل كلود كود سي ال آي","en":"Production-ready skills for Claude Code CLI - Cloudflare, React, Tailwind v4, and AI integrations"},"definition":{"en":"Production-ready skills for Claude Code CLI - Cloudflare, React, Tailwind v4, and AI integrations"},"features":{"zh":["支持 Cloudflare 和 React","集成 Tailwind v4 和 AI","基于 Pyodide 的 Python 运行时环境","支持 uv 和 Node.js","快速初始化项目"],"ja":["Cloudflare と React をサポート","Tailwind v4 と AI を統合","Pyodide ベースの Python ランタイム環境","uv と Node.js をサポート","プロジェクトの迅速な初期化"],"ko":["Cloudflare와 React 지원","Tailwind v4 및 AI 통합","Pyodide 기반의 Python 런타임 환경","uv 및 Node.js 지원","프로젝트 빠른 초기화"],"es":["Compatibilidad con Pyodide","Soporte para Python 3.12+","Integración con Claude Code CLI","Uso de workers-py y workers-runtime-sdk","Compatibilidad con Wrangler"],"fr":["Compatibilité avec Pyodide","Prise en charge de Python 3.12+","Intégration avec Claude Code CLI","Utilisation de workers-py et workers-runtime-sdk","Compatibilité avec Wrangler"],"de":["Kompatibilität mit Pyodide","Unterstützung für Python 3.12+","Integration mit Claude Code CLI","Verwendung von workers-py und workers-runtime-sdk","Kompatibilität mit Wrangler"],"pt":["Compatibilidade com Python 3.12+","Execução de código Python na nuvem","Integração com o Claude Code CLI","Utiliza o Pyodide para compilar código Python para WebAssembly","Inclui pacotes workers-py e workers-runtime-sdk"],"ru":["Совместимость с Python 3.12+","Выполнение кода Python в облаке","Интеграция с Claude Code CLI","Использует Pyodide для компиляции кода Python в WebAssembly","Включает пакеты workers-py и workers-runtime-sdk"],"ar":["توافق مع بایتون 3.12+","تشغيل كود بایتون في السحابة","دمج مع كلود كود سي ال آي","يستخدم بايوديد لتحويل كود بایتون إلى ويب أسمبلي","يضم حزمات وركرز-بي و وركرز-رنタイم-إس دي كي"]},"keywords":{"zh":["Cloudflare Python Workers","Pyodide","Python 运行时环境","Cloudflare","React","Tailwind v4","AI 集成","开发和部署"],"ja":["Cloudflare Python Workers","Pyodide","Python ランタイム環境","Cloudflare","React","Tailwind v4","AI 統合","開発とデプロイ"],"ko":["Cloudflare Python Workers","Pyodide","Python 런타임 환경","Cloudflare","React","Tailwind v4","AI 통합","개발 및 배포"],"es":["trabajadores de Python de Cloudflare","Cloudflare Python Worker","Claude Code CLI","Pyodide","Python 3.12+","workers-py","workers-runtime-sdk","Wrangler"],"fr":["workers Python de Cloudflare","Cloudflare Python Worker","Claude Code CLI","Pyodide","Python 3.12+","workers-py","workers-runtime-sdk","Wrangler"],"de":["Cloudflare Python Worker","Cloudflare Worker","Claude Code CLI","Pyodide","Python 3.12+","workers-py","workers-runtime-sdk","Wrangler"],"pt":["trabalhadores python cloudflare","cloudflare python workers","claude code cli","python na nuvem","pyodide","webassembly"],"ru":["работники python cloudflare","cloudflare python работники","claude code cli","python в облаке","pyodide","webassembly"],"ar":["عاملو بایتون كلاودفلير","كلاودفلير عاملو بایتون","كلود كود سي ال آي","بایتون في السحابة","بايوديد","ويب أسمبلي"]}},"owner":"evolv3ai","repo":"claude-skills-archive","repoPath":"evolv3ai/claude-skills-archive","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.581Z","topics":[],"category":"community","skillMd":{"name":"cloudflare-python-workers","description":"|","bodyPreview":"# Cloudflare Python Workers\n\n**Status**: Beta (requires `python_workers` compatibility flag)\n**Runtime**: Pyodide (Python 3.12+ compiled to WebAssembly)\n**Package Versions**: workers-py@1.7.0, workers-runtime-sdk@0.3.1, wrangler@4.58.0\n**Last Verified**: 2026-01-21\n\n## Quick Start (5 Minutes)\n\n### 1. Prerequisites\n\nEnsure you have installed:\n- [uv](https://docs.astral.sh/uv/#installation) - Python package manager\n- [Node.js](https://nodejs.org/) - Required for Wrangler\n\n### 2. Initialize Project","body":"# Cloudflare Python Workers\n\n**Status**: Beta (requires `python_workers` compatibility flag)\n**Runtime**: Pyodide (Python 3.12+ compiled to WebAssembly)\n**Package Versions**: workers-py@1.7.0, workers-runtime-sdk@0.3.1, wrangler@4.58.0\n**Last Verified**: 2026-01-21\n\n## Quick Start (5 Minutes)\n\n### 1. Prerequisites\n\nEnsure you have installed:\n- [uv](https://docs.astral.sh/uv/#installation) - Python package manager\n- [Node.js](https://nodejs.org/) - Required for Wrangler\n\n### 2. Initialize Project\n\n```bash\n# Create project directory\nmkdir my-python-worker && cd my-python-worker\n\n# Initialize Python project\nuv init\n\n# Install pywrangler\nuv tool install workers-py\n\n# Initialize Worker configuration\nuv run pywrangler init\n```\n\n### 3. Create Entry Point\n\nCreate `src/entry.py`:\n\n```python\nfrom workers import WorkerEntrypoint, Response\n\nclass Default(WorkerEntrypoint):\n    async def fetch(self, request):\n        return Response(\"Hello from Python Worker!\")\n```\n\n### 4. Configure wrangler.jsonc\n\n```jsonc\n{\n  \"name\": \"my-python-worker\",\n  \"main\": \"src/entry.py\",\n  \"compatibility_date\": \"2025-12-01\",\n  \"compatibility_flags\": [\"python_workers\"]\n}\n```\n\n### 5. Run Locally\n\n```bash\nuv run pywrangler dev\n# Visit http://localhost:8787\n```\n\n### 6. Deploy\n\n```bash\nuv run pywrangler deploy\n```\n\n---\n\n## Migration from Pre-December 2025 Workers\n\nIf you created a Python Worker before December 2025, you were limited to built-in packages. With pywrangler (Dec 2025), you can now deploy with external packages.\n\n**Old Approach** (no longer needed):\n```python\n# Limited to built-in packages only\n# Could only use httpx, aiohttp, beautifulsoup4, etc.\n# Error: \"You cannot yet deploy Python Workers that depend on\n# packages defined in requirements.txt [code: 10021]\"\n```\n\n**New Approach** (pywrangler):\n```toml\n# pyproject.toml\n[project]\ndependencies = [\"fastapi\", \"any-pyodide-compatible-package\"]\n```\n\n```bash\nuv tool install workers-py\nuv run pywrangler deploy  # Now works!\n```\n\n**Historical Timeline**:\n- **April 2024 - Dec 2025**: Package deployment completely blocked\n- **Dec 8, 2025**: Pywrangler released, enabling package deployment\n- **Jan 2026**: Open beta with full package support\n\n**See**: [Package deployment issue history](https://github.com/cloudflare/workers-sdk/issues/6613)\n\n---\n\n## Core Concepts\n\n### WorkerEntrypoint Class Pattern\n\nAs of August 2025, Python Workers use a class-based pattern (not global handlers):\n\n```python\nfrom workers import WorkerEntrypoint, Response\n\nclass Default(WorkerEntrypoint):\n    async def fetch(self, request):\n        # Access bindings via self.env\n        value = await self.env.MY_KV.get(\"key\")\n\n        # Parse request\n        url = request.url\n        method = request.method\n\n        return Response(f\"Method: {method}, URL: {url}\")\n```\n\n### Accessing Bindings\n\nAll Cloudflare bindings are accessed via `self.env`:\n\n```python\nclass Default(WorkerEntrypoint):\n    async def fetch(self, request):\n        # D1 Database\n        result = await self.env.DB.prepare(\"SELECT * FROM users\").all()\n\n        # KV Storage\n        value = await self.env.MY_KV.get(\"key\")\n        await self.env.MY_KV.put(\"key\", \"value\")\n\n        # R2 Object Storage\n        obj = await self.env.MY_BUCKET.get(\"file.txt\")\n\n        # Workers AI\n        response = await self.env.AI.run(\"@cf/meta/llama-2-7b-chat-int8\", {\n            \"prompt\": \"Hello!\"\n        })\n\n        return Response(\"OK\")\n```\n\n**Supported Bindings**:\n- D1 (SQL database)\n- KV (key-value storage)\n- R2 (object storage)\n- Workers AI\n- Vectorize\n- Durable Objects\n- Queues\n- Analytics Engine\n\nSee [Cloudflare Bindings Documentation](https://developers.cloudflare.com/workers/runtime-apis/bindings/) for details.\n\n### Request/Response Handling\n\n```python\nfrom workers import WorkerEntrypoint, Response\nimport json\n\nclass Default(WorkerEntrypoint):\n    async def fetch(self, request):\n        # Parse JSON body\n        if request.method == \"POST\":\n            body = await request.json()\n            return Response(\n                json.dumps({\"received\": body}),\n                headers={\"Content-Type\": \"application/json\"}\n            )\n\n        # Query parameters\n        url = URL(request.url)\n        name = url.searchParams.get(\"name\", \"World\")\n\n        return Response(f\"Hello, {name}!\")\n```\n\n### Scheduled Handlers (Cron)\n\n```python\nfrom workers import handler\n\n@handler\nasync def on_scheduled(event, env, ctx):\n    # Run on cron schedule\n    print(f\"Cron triggered at {event.scheduledTime}\")\n\n    # Do work...\n    await env.MY_KV.put(\"last_run\", str(event.scheduledTime))\n```\n\nConfigure in wrangler.jsonc:\n\n```jsonc\n{\n  \"triggers\": {\n    \"crons\": [\"*/5 * * * *\"]  // Every 5 minutes\n  }\n}\n```\n\n---\n\n## Python Workflows\n\nPython Workflows enable durable, multi-step automation with automatic retries and state persistence.\n\n### Why Decorator Pattern?\n\nPython Workflows use the `@step.do()` decorator pattern because **Python does not easily support anonymous callbacks** (unlike JavaScript/TypeScript which allows inline arrow functions). This is a fundamental language difference, not a limitation of Cloudflare''s implementation.\n\n**JavaScript Pattern** (doesn''t translate):\n```javascript\nawait step.do(\"my step\", async () => {\n  // Inline callback\n  return result;\n});\n```\n\n**Python Pattern** (required):\n```python\n@step.do(\"my step\")\nasync def my_step():\n    # Named function with decorator\n    return result\n\nresult = await my_step()\n```\n\n**Source**: [Python Workflows Blog](https://blog.cloudflare.com/python-workflows/)\n\n### Concurrency with asyncio.gather\n\nPyodide captures JavaScript promises (thenables) and proxies them as Python awaitables. This enables `Promise.all`-equivalent behavior using standard Python async patterns:\n\n```python\nimport asyncio\n\n@step.do(\"step_a\")\nasync def step_a():\n    return \"A\"\n\n@step.do(\"step_b\")\nasync def step_b():\n    return \"B\"\n\n# Concurrent execution (like Promise.all)\nresults = await asyncio.gather(step_a(), step_b())\n# results = [\"A\", \"B\"]\n```\n\n**Why This Works**: JavaScript promises from workflow steps are proxied as Python awaitables, allowing standard asyncio concurrency primitives.\n\n**Source**: [Python Workflows Blog](https://blog.cloudflare.com/python-workflows/)\n\n### Basic Workflow\n\n```python\nfrom workers import WorkflowEntrypoint, WorkerEntrypoint, Response\n\nclass MyWorkflow(WorkflowEntrypoint):\n    async def run(self, event, step):\n        # Step 1\n        @step.do(\"fetch data\")\n        async def fetch_data():\n            response = await fetch(\"https://api.example.com/data\")\n            return await response.json()\n\n        data = await fetch_data()\n\n        # Step 2: Sleep\n        await step.sleep(\"wait\", \"10 seconds\")\n\n        # Step 3: Process\n        @step.do(\"process data\")\n        async def process_data():\n            return {\"processed\": True, \"count\": len(data)}\n\n        result = await process_data()\n        return result\n\n\nclass Default(WorkerEntrypoint):\n    async def fetch(self, request):\n        # Create workflow instance\n        instance = await self.env.MY_WORKFLOW.create()\n        return Response(f\"Workflow started: {instance.id}\")\n```\n\n### DAG Dependencies\n\nDefine step dependencies for parallel execution:\n\n```python\nclass MyWorkflow(WorkflowEntrypoint):\n    async def run(self, event, step):\n        @step.do(\"step_a\")\n        async def step_a():\n            return \"A done\"\n\n        @step.do(\"step_b\")\n        async def step_b():\n            return \"B done\"\n\n        # step_c waits for both step_a and step_b\n        @step.do(\"step_c\", depends=[step_a, step_b], concurrent=True)\n        async def step_c(result_a, result_b):\n            return f\"C received: {result_a}, {result_b}\"\n\n        return await step_c()\n```\n\n### Workflow Configuration\n\n```jsonc\n{\n  \"compatibility_flags\": [\"python_workers\", \"python_workflows\"],\n  \"compatibility_date\": \"2025-12-01\",\n  \"workflows\": [\n    {\n      \"name\": \"my-workflow\",\n      \"binding\": \"MY_WORKFLOW\",\n      \"class_name\": \"MyWorkflow\"\n    }\n  ]\n}\n```\n\n---\n\n## Package Management\n\n### pyproject.toml Configuration\n\n```toml\n[project]\nname = \"my-python-worker\"\nversion = \"0.1.0\"\nrequires-python = \">=3.12\"\ndependencies = [\n    \"beautifulsoup4\",\n    \"httpx\"\n]\n\n[dependency-groups]\ndev = [\n    \"workers-py\",\n    \"workers-runtime-sdk\"\n]\n```\n\n### Supported Packages\n\nPython Workers support:\n- **Pure Python packages** from PyPI\n- **Pyodide packages** (pre-built for WebAssembly)\n\nSee [Pyodide packages list](https://pyodide.org/en/stable/usage/packages-in-pyodide.html).\n\n### HTTP Clients\n\nOnly **async** HTTP libraries work:\n\n```python\n# ✅ WORKS - httpx (async)\nimport httpx\n\nasync with httpx.AsyncClient() as client:\n    response = await client.get(\"https://api.example.com\")\n\n# ✅ WORKS - aiohttp\nimport aiohttp\n\nasync with aiohttp.ClientSession() as session:\n    async with session.get(\"https://api.example.com\") as response:\n        data = await response.json()\n\n# ❌ DOES NOT WORK - requests (sync)\nimport requests  # Will fail!\n```\n\n### Requesting New Packages\n\nRequest support for new packages at:\nhttps://github.com/cloudflare/workerd/discussions/categories/python-packages\n\n---\n\n## FFI (Foreign Function Interface)\n\nAccess JavaScript APIs from Python via Pyodide''s FFI:\n\n### JavaScript Globals\n\n```python\nfrom js import fetch, console, Response as JSResponse\n\nclass Default(WorkerEntrypoint):\n    async def fetch(self, request):\n        # Use JavaScript fetch\n        response = await fetch(\"https://api.example.com\")\n        data = await response.json()\n\n        # Console logging\n        console.log(\"Fetched data:\", data)\n\n        # Return JavaScript Response\n        return JSResponse.new(\"Hello!\")\n```\n\n### Type Conversions\n\n**Important**: `to_py()` is a METHOD on JavaScript objects, not a standalone function. Only `to_js()` is a function.\n\n```python\nfrom js import Object\nfrom pyodide.ffi import to_js\n\n# ❌ WRONG - ImportError!\nfrom pyodide.ffi import to_py\npython_data = to_py(js_data)\n\n# ✅ CORRECT - to_py() is a method\nasync def fetch(self, request):\n    data = await request.json()  # Returns JS object\n    python_data = data.to_py()   # Convert to Python dict\n\n# Convert Python dict to JavaScript object\npython_dict = {\"name\": \"test\", \"count\": 42}\njs_object = to_js(python_dict, dict_converter=Object.fromEntries)\n\n# Use in Response\nreturn Response(to_js({\"status\": \"ok\"}))\n```\n\n**Source**: [GitHub Issue #3322](https://github.com/cloudflare/workerd/issues/3322) (Pyodide maintainer clarification)\n\n---\n\n## Known Issues Prevention\n\nThis skill prevents **11 documented issues**:\n\n### Issue #1: Legacy Handler Pattern\n\n**Error**: `TypeError: on_fetch is not defined`\n\n**Why**: Handler pattern changed in August 2025.\n\n```python\n# ❌ OLD (deprecated)\n@handler\nasync def on_fetch(request):\n    return Response(\"Hello\")\n\n# ✅ NEW (current)\nclass Default(WorkerEntrypoint):\n    async def fetch(self, request):\n        return Response(\"Hello\")\n```\n\n### Issue #2: Sync HTTP Libraries\n\n**Error**: `RuntimeError: cannot use blocking call in async context`\n\n**Why**: Python Workers run async-only. Sync libraries block the event loop.\n\n```python\n# ❌ FAILS\nimport requests\nresponse = requests.get(\"https://api.example.com\")\n\n# ✅ WORKS\nimport httpx\nasync with httpx.AsyncClient() as client:\n    response = await client.get(\"https://api.example.com\")\n```\n\n### Issue #3: Native/Compiled Packages\n\n**Error**: `ModuleNotFoundError: No module named ''numpy''` (or similar)\n\n**Why**: Only pure Python packages work. Native C extensions are not supported.\n\n**Solution**: Use Pyodide-compatible alternatives or check [Pyodide packages](https://pyodide.org/en/stable/usage/packages-in-pyodide.html).\n\n### Issue #4: Missing Compatibility Flags\n\n**Error**: `Error: Python Workers require the python_workers compatibility flag`\n\n**Fix**: Add to wrangler.jsonc:\n\n```jsonc\n{\n  \"compatibility_flags\": [\"python_workers\"]\n}\n```\n\nFor Workflows, also add `\"python_workflows\"`.\n\n### Issue #5: I/O Outside Workflow Steps\n\n**Error**: Workflow state not persisted correctly\n\n**Why**: All I/O must happen inside `@step.do` for durability.\n\n```python\n# ❌ BAD - fetch outside step\nresponse = await fetch(\"https://api.example.com\")\n@step.do(\"use data\")\nasync def use_data():\n    return await response.json()  # response may be stale on retry\n\n# ✅ GOOD - fetch inside step\n@step.do(\"fetch and use\")\nasync def fetch_and_use():\n    response = await fetch(\"https://api.example.com\")\n    return await response.json()\n```\n\n### Issue #6: Type Serialization Errors\n\n**Error**: `TypeError: Object of type X is not JSON serializable`\n\n**Why**: Workflow step return values must be JSON-serializable.\n\n**Fix**: Convert complex objects before returning:\n\n```python\n@step.do(\"process\")\nasync def process():\n    # Convert datetime to string\n    return {\"timestamp\": datetime.now().isoformat()}\n```\n\n### Issue #7: Cold Start Performance\n\n**Note**: Python Workers have higher cold starts than JavaScript. With Wasm memory snapshots (Dec 2025), heavy packages like FastAPI and Pydantic now load in **~1 second** (down from ~10 seconds previously), but this is still ~2x slower than JavaScript Workers (~50ms).\n\n**Performance Numbers** (as of Dec 2025):\n- **Before snapshots**: ~10 seconds for FastAPI/Pydantic\n- **After snapshots**: ~1 second (10x improvement)\n- **JavaScript equivalent**: ~50ms\n\n**Mitigation**:\n- Minimize top-level imports\n- Use lazy loading for heavy packages\n- Consider JavaScript Workers for latency-critical paths\n- Wasm snapshots automatically improve cold starts (no config needed)\n\n**Source**: [Python Workers Redux Blog](https://blog.cloudflare.com/python-workers-advancements/) | [InfoQ Coverage](https://www.infoq.com/news/2025/12/cloudflare-wasm-python-snapshot/)\n\n### Issue #8: Package Installation Failures\n\n**Error**: `Failed to install package X`\n\n**Causes**:\n- Package has native dependencies\n- Package not in Pyodide ecosystem\n- Network issues during bundling\n\n**Fix**: Check package compatibility, use alternatives, or request support.\n\n### Issue #9: Dev Registry Breaks JS-to-Python RPC\n\n**Error**: `Network connection lost` when calling Python Worker from JavaScript Worker\n**Source**: [GitHub Issue #11438](https://github.com/cloudflare/workers-sdk/issues/11438)\n\n**Why It Happens**: Dev registry doesn''t properly route RPC calls between separately-run Workers in different terminals.\n\n**Prevention**:\n```bash\n# ❌ Doesn''t work - separate terminals\n# Terminal 1: npx wrangler dev (JS worker)\n# Terminal 2: npx wrangler dev (Python worker)\n# Result: Network connection lost error\n\n# ✅ Works - single wrangler instance\nnpx wrangler dev -c ts/wrangler.jsonc -c py/wrangler.jsonc\n```\n\nRun both workers in a single wrangler instance to enable proper RPC communication.\n\n### Issue #10: HTMLRewriter Memory Limit with Data URLs\n\n**Error**: `TypeError: Parser error: The memory limit has been exceeded`\n**Source**: [GitHub Issue #10814](https://github.com/cloudflare/workers-sdk/issues/10814)\n\n**Why It Happens**: Large inline `data:` URLs (>10MB) in HTML trigger parser memory limits. This is NOT about response size—10MB plain text works fine, but 10MB HTML with embedded data URLs fails. Common with Python Jupyter Notebooks that use inline images for plots.\n\n**Prevention**:\n```python\n# ❌ FAILS - HTMLRewriter triggered on notebook HTML with data: URLs\nresponse = await fetch(\"https://origin.example.com/notebook.html\")\nreturn response  # Crashes if HTML contains large data: URLs\n\n# ✅ WORKS - Stream directly or use text/plain\nresponse = await fetch(\"https://origin.example.com/notebook.html\")\nheaders = {\"Content-Type\": \"text/plain\"}  # Bypass parser\nreturn Response(await response.text(), headers=headers)\n```\n\n**Workarounds**:\n- Avoid HTMLRewriter on notebook content (stream directly)\n- Pre-process notebooks to extract data URLs to external files\n- Use `text/plain` content-type to bypass parser\n\n### Issue #11: PRNG Cannot Be Seeded During Initialization\n\n**Error**: Deployment fails with user error\n**Source**: [Python Workers Redux Blog](https://blog.cloudflare.com/python-workers-advancements/)\n\n**Why It Happens**: Wasm snapshots don''t support PRNG initialization before request handlers. If you call pseudorandom number generator APIs (like `random.seed()`) during module initialization, deployment FAILS.\n\n**Prevention**:\n```python\nimport random\n\n# ❌ FAILS deployment - module-level PRNG call\nrandom.seed(42)\n\nclass Default(WorkerEntrypoint):\n    async def fetch(self, request):\n        return Response(str(random.randint(1, 100)))\n\n# ✅ WORKS - PRNG calls inside handlers\nclass Default(WorkerEntrypoint):\n    async def fetch(self, request):\n        random.seed(42)  # Initialize inside handler\n        return Response(str(random.randint(1, 100)))\n```\n\nOnly call PRNG functions inside request handlers, not at module level.\n\n---\n\n## Best Practices\n\n### Always Do\n\n- Use `WorkerEntrypoint` class pattern\n- Use async HTTP clients (httpx, aiohttp)\n- Put all I/O inside workflow steps\n- Add `python_workers` compatibility flag\n- Use `self.env` for all bindings\n- Return JSON-serializable data from workflow steps\n\n### Never Do\n\n- Use sync HTTP libraries (requests)\n- Use native/compiled packages\n- Perform I/O outside workflow steps\n- Use legacy `@handler` decorator for fetch\n- Expect JavaScript-level cold start times\n\n---\n\n## Framework Note: FastAPI\n\nFastAPI can work with Python Workers but with limitations:\n\n```python\nfrom fastapi import FastAPI\nfrom workers import WorkerEntrypoint\n\napp = FastAPI()\n\n@app.get(\"/\")\nasync def root():\n    return {\"message\": \"Hello from FastAPI\"}\n\nclass Default(WorkerEntrypoint):\n    async def fetch(self, request):\n        # Route through FastAPI\n        return await app(request)\n```\n\n**Limitations**:\n- Async-only (no sync endpoints)\n- No WSGI middleware\n- Beta stability\n\nSee [Cloudflare FastAPI example](https://developers.cloudflare.com/workers/languages/python/) for details.\n\n---\n\n## Official Documentation\n\n- [Python Workers Overview](https://developers.cloudflare.com/workers/languages/python/)\n- [Python Workers Basics](https://developers.cloudflare.com/workers/languages/python/basics/)\n- [How Python Workers Work](https://developers.cloudflare.com/workers/languages/python/how-python-workers-work/)\n- [Python Packages](https://developers.cloudflare.com/workers/languages/python/packages/)\n- [FFI (Foreign Function Interface)](https://developers.cloudflare.com/workers/languages/python/ffi/)\n- [Python Workflows](https://developers.cloudflare.com/workflows/python/)\n- [Pywrangler CLI](https://github.com/cloudflare/workers-py)\n- [Pyodide Package List](https://pyodide.org/en/stable/usage/packages-in-pyodide.html)\n\n---\n\n## Dependencies\n\n```json\n{\n  \"workers-py\": \"1.7.0\",\n  \"workers-runtime-sdk\": \"0.3.1\",\n  \"wrangler\": \"4.58.0\"\n}\n```\n\n**Note**: Always pin versions for reproducible builds. Check [PyPI workers-py](https://pypi.org/project/workers-py/) for latest releases.\n\n---\n\n## Production Validation\n\n- Cloudflare changelog: Dec 8, 2025 (Pywrangler + cold start improvements)\n- workers-py 1.7.0: Latest stable (Jan 2026)\n- Python Workflows beta: Aug 22, 2025\n- Handler pattern change: Aug 14, 2025\n\n**Compatibility Date Guidance**:\n- Use `2025-12-01` for new projects (latest features including pywrangler improvements)\n- Use `2025-08-01` only if you need to match older production Workers\n"},"lastSynced":"2026-02-20T05:10:46.601Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloudflare-focused Agents needing advanced Python worker integration and WebAssembly compilation capabilities.","zh":"适合需要高级Python worker集成和WebAssembly编译能力的Cloudflare专用Agent。","ja":"Cloudflareに焦点を当てたエージェントが高度なPythonワーカー統合とWebAssemblyコンパイル機能を必要とする場合に最適です。","ko":"클라우드플레어에 중점을 둔 에이전트가 고급 Python 워커 통합 및 WebAssembly 컴파일 기능을 필요로 할 때 완벽합니다.","es":"Perfecto para agentes centrados en Cloudflare que necesitan una integración avanzada de trabajadores de Python y capacidades de compilación de WebAssembly.","fr":"Parfait pour les agents axés sur Cloudflare nécessitant une intégration avancée des workers Python et des capacités de compilation WebAssembly.","de":"Perfekt für Cloudflare-fokussierte Agenten, die eine erweiterte Python-Worker-Integration und WebAssembly-Compilierungsfunktionen benötigen.","pt":"Perfeito para Agentes focados em Cloudflare que necessitam de integração avançada de trabalhador Python e capacidades de compilação de WebAssembly.","ru":"Идеально подходит для агентов, ориентированных на Cloudflare, которым необходима продвинутая интеграция рабочих процессов Python и возможностей компиляции WebAssembly.","ar":"مثالي لعميل 云فلير الذي يحتاج إلى دمج متقدم للعامل بايثون وقدرات تجميع ويب أсемبلي."},"recommendation":{"en":"Empowers agents to leverage Cloudflare''s edge computing with Pyodide, utilizing Python 3.12+ compiled to WebAssembly, and integrating with workers-py and workers-runtime-sdk for seamless deployment and management.","zh":"赋予代理人利用Cloudflare的边缘计算能力，使用Pyodide，利用Python 3.12+编译为WebAssembly，并与workers-py和workers-runtime-sdk集成，以实现无缝的部署和管理。","ja":"エージェントがCloudflareのエッジコンピューティングをPyodideで利用できるようにし、Python 3.12以上をWebAssemblyにコンパイルし、workers-pyとworkers-runtime-sdkと統合して、シームレスなデプロイと管理を可能にします。","ko":"에이전트가 클라우드플레어의 에지 컴퓨팅을 Pyodide로 활용할 수 있도록 하여 Python 3.12 이상을 WebAssembly로 컴파일하고 workers-py와 workers-runtime-sdk와 통합하여 무중단 배포 및 관리를 가능하게 합니다.","es":"Permite a los agentes aprovechar la informática de borde de Cloudflare con Pyodide, utilizando Python 3.12+ compilado a WebAssembly, e integrándose con workers-py y workers-runtime-sdk para una implementación y administración sin problemas.","fr":"Permet aux agents d''exploiter l''informatique de pointe de Cloudflare avec Pyodide, en utilisant Python 3.12+ compilé en WebAssembly, et en s''intégrant avec workers-py et workers-runtime-sdk pour un déploiement et une gestion sans heurts.","de":"Ermöglicht es Agenten, Cloudflares Edge-Computing mit Pyodide zu nutzen, indem Python 3.12+ in WebAssembly kompiliert und mit workers-py und workers-runtime-sdk für eine nahtlose Bereitstellung und Verwaltung integriert wird.","pt":"Habilita os agentes a aproveitar a computação de bordo da Cloudflare com Pyodide, utilizando Python 3.12+ compilado para WebAssembly, e integrando com workers-py e workers-runtime-sdk para implantação e gerenciamento sem problemas.","ru":"Наделяет агентов возможностью использовать вычисления на краю сети Cloudflare с помощью Pyodide, используя Python 3.12+ скомпилированный в WebAssembly, и интегрируя с workers-py и workers-runtime-sdk для бесшовного развертывания и управления.","ar":"يُ�权 العميل باستخدام الحوسبة على الحافة من.cloudflare مع pyodide ، باستخدام بايثون 3.12+ المترجم إلى ويب أсемبلي ، والتحكم في workers-py و workers-runtime-sdk من أجل نشر و إدارة بدون مشاكل."},"useCases":{"en":["Deploying serverless Python applications on Cloudflare''s edge network","Automating content delivery and security configurations with Cloudflare Workers","Debugging and optimizing Python worker performance using Wrangler and Pyodide"],"zh":["在Cloudflare的边缘网络上部署无服务器Python应用程序","使用Cloudflare Workers自动化内容交付和安全配置","使用Wrangler和Pyodide调试和优化Python worker性能"],"ja":["Cloudflareのエッジネットワーク上でサーバーレスPythonアプリケーションをデプロイする","Cloudflare Workersを使用してコンテンツ配信とセキュリティ設定を自動化する","WranglerとPyodideを使用してPythonワーカーのパフォーマンスをデバッグおよび最適化する"],"ko":["클라우드플레어의 에지 네트워크에서 서버리스 Python 애플리케이션을 배포하는 것","클라우드플레어 워커를 사용하여 콘텐츠 전송 및 보안 구성 자동화","Wrangler 및 Pyodide를 사용하여 Python 워커 성능을 디버그하고 최적화"],"es":["Implementar aplicaciones de Python sin servidor en la red de borde de Cloudflare","Automatizar la configuración de entrega y seguridad de contenido con Cloudflare Workers","Depurar y optimizar el rendimiento de los workers de Python utilizando Wrangler y Pyodide"],"fr":["Déployer des applications Python sans serveur sur le réseau de pointe de Cloudflare","Automatiser la configuration de la livraison et de la sécurité du contenu avec Cloudflare Workers","Déboguer et optimiser les performances des workers Python en utilisant Wrangler et Pyodide"],"de":["Serverlose Python-Anwendungen im Cloudflare-Edge-Netzwerk bereitstellen","Inhaltslieferungs- und Sicherheitskonfigurationen mit Cloudflare Workers automatisieren","Python-Worker-Leistung mit Wrangler und Pyodide debuggen und optimieren"],"pt":["Implantação de aplicações Python sem servidor na rede de bordo da Cloudflare","Automatização de configurações de entrega e segurança de conteúdo com Cloudflare Workers","Depuração e otimização do desempenho do trabalhador Python usando Wrangler e Pyodide"],"ru":["Развертывание серверных приложений Python в сети края Cloudflare","Автоматизация настроек доставки и безопасности контента с помощью Cloudflare Workers","Отладка и оптимизация производительности рабочего процесса Python с помощью Wrangler и Pyodide"],"ar":["نشر تطبيقات بايثون بدون خادم على شبكة الحافة من.cloudflare","توفير إعدادات تسليم المحتوى والأمان مع عميل 云فلير","تصحيح أخطاء و تحسين أداء عامل بايثون باستخدام wrangler و pyodide"]},"limitations":{"en":["Requires python_workers compatibility flag","Limited to Python 3.12+ due to Pyodide compilation requirements","Dependent on Node.js for Wrangler functionality"],"zh":["需要python_workers兼容性标志","由于Pyodide编译要求，仅限Python 3.12+","依赖于Node.js的Wrangler功能"],"ja":["python_workers互換性フラグが必要","Pyodideコンパイル要件により、Python 3.12+に限定される","Wranglerの機能としてNode.jsに依存する"],"ko":["python_workers 호환성 플래그가 필요","Pyodide 컴파일 요구 사항으로 인해 Python 3.12+로 제한","Wrangler 기능으로 Node.js에 의존"],"es":["Requiere la compatibilidad con la bandera python_workers","Limitado a Python 3.12+ debido a los requisitos de compilación de Pyodide","Dependiente de Node.js para la funcionalidad de Wrangler"],"fr":["Nécessite la compatibilité du drapeau python_workers","Limité à Python 3.12+ en raison des exigences de compilation de Pyodide","Dépendant de Node.js pour la fonctionnalité de Wrangler"],"de":["Benötigt die Kompatibilitätsflagge python_workers","Begrenzt auf Python 3.12+ aufgrund der Kompilierungsanforderungen von Pyodide","Abhängig von Node.js für die Wrangler-Funktionalität"],"pt":["Requer compatibilidade com a flag python_workers","Limitado ao Python 3.12+ devido aos requisitos de compilação do Pyodide","Dependente do Node.js para funcionalidade do Wrangler"],"ru":["Требует совместимости с флагом python_workers","Ограничен Python 3.12+ из-за требований компиляции Pyodide","Зависит от Node.js для функциональности Wrangler"],"ar":["يتطلب توافق مع علم python_workers","محدد ببايثون 3.12+ بسبب متطلبات ترجمة pyodide","يعتمد على node.js لتشغيل wrangler"]},"version":3},"contentHash":"12a6035f83a48fea0cb08443b291e018dafe97a2f14b21db685e7176cbaaaa1c","qualityScore":50}');
